@router.patch({{path}}, response_model=ChildRead)
async def patch_child(parent_id: int, child_id: int, data: ChildPatch) -> Child:
    """Patch child."""
    async def write(session: AsyncClientSession) -> Child:
        """Write."""
        row = await _require_child(parent_id, child_id, session)
        changes = _encode(model_values(data, exclude_unset=True))
        if changes:
            changes["updated_at"] = datetime.now(UTC)
            await Child.get_pymongo_collection().update_one({"_id": row.id}, {"$set": changes}, session=session)
        return await _require_child(parent_id, row.id, session)
    return await transaction(write)
